(function(G){
var checks=G.__rangeChecks=[];
function check(name,fn){var ok=false,error='';try{ok=!!fn();}catch(e){error=e.name+': '+e.message;}checks.push({name:name,ok:ok,error:error});}
function box(markup){var n=document.createElement('div');n.innerHTML=markup;document.body.appendChild(n);return n;}
check('Range starts at document',function(){var r=new Range();return r.startContainer===document&&r.collapsed&&r.startOffset===0;});
check('JS insertion shifts live parent boundary',function(){var n=box('<b>a</b><i>b</i>'),r=new Range();r.setStart(n,1);r.setEnd(n,2);n.insertBefore(document.createElement('u'),n.firstChild);return r.startOffset===2&&r.endOffset===3;});
check('removal relocates text boundaries',function(){var n=box('<b>abc</b><i>def</i>'),r=new Range();r.setStart(n.firstChild.firstChild,1);r.setEnd(n.lastChild.firstChild,2);n.removeChild(n.firstChild);return r.startContainer===n&&r.startOffset===0&&r.endContainer===n.firstChild.firstChild;});
check('detached range remains live',function(){var n=document.createElement('p'),t=document.createTextNode('abc');n.appendChild(t);var r=new Range();r.setStart(t,2);r.setEnd(t,3);t.insertData(0,'x');return r.startOffset===3&&r.endOffset===4;});
check('UTF16 insert and replace boundaries',function(){var n=box('A😀中文Z'),t=n.firstChild,r=new Range();r.setStart(t,3);r.setEnd(t,6);t.insertData(1,'好');if(r.startOffset!==4||r.endOffset!==7)return false;t.replaceData(2,3,'Q');return r.startOffset===2&&r.endOffset===5&&t.data==='A好Q文Z';});
check('whole data replacement resets boundaries',function(){var t=document.createTextNode('abc'),r=new Range();r.setStart(t,1);r.setEnd(t,3);t.data='longer';return r.startOffset===0&&r.endOffset===0;});
check('splitText transfers boundaries to tail',function(){var n=box('abcdef'),t=n.firstChild,r=new Range();r.setStart(t,4);r.setEnd(t,6);var tail=t.splitText(3);return r.startContainer===tail&&r.startOffset===1&&r.endOffset===3&&tail.data==='def';});
check('splitText preserves parent boundary after text',function(){var n=box('abcd'),r=new Range();r.setStart(n,1);r.collapse(true);n.firstChild.splitText(2);return r.startOffset===2&&r.endOffset===2;});
check('UTF16 surrogate half split round trips',function(){var n=box('A😀Z'),tail=n.firstChild.splitText(2);return n.firstChild.data.length===2&&n.firstChild.data.charCodeAt(1)===0xd83d&&tail.data.charCodeAt(0)===0xde00;});
check('invalid boundary throws without changing range',function(){var t=document.createTextNode('abc'),r=new Range();r.selectNodeContents(t);try{r.setStart(t,4);}catch(e){return e.name==='IndexSizeError'&&r.startOffset===0&&r.endOffset===3;}return false;});
check('reversed boundary collapses',function(){var t=document.createTextNode('abcdef'),r=new Range();r.setStart(t,1);r.setEnd(t,3);r.setStart(t,5);return r.collapsed&&r.endOffset===5;});
check('compareBoundaryPoints ordering modes',function(){var t=document.createTextNode('abcdef'),a=new Range(),b=new Range();a.setStart(t,1);a.setEnd(t,3);b.setStart(t,2);b.setEnd(t,5);return a.compareBoundaryPoints(0,b)===-1&&a.compareBoundaryPoints(1,b)===1&&a.compareBoundaryPoints(2,b)===-1&&a.compareBoundaryPoints(3,b)===-1;});
check('cloneContents keeps partial nested structure',function(){var n=box('<b>abc</b><i>def</i><u>ghi</u>'),r=new Range();r.setStart(n.firstChild.firstChild,1);r.setEnd(n.lastChild.firstChild,2);var f=r.cloneContents();return f.childNodes.length===3&&f.firstChild.tagName==='B'&&f.firstChild.textContent==='bc'&&f.lastChild.textContent==='gh'&&n.textContent==='abcdefghi'&&r.toString()==='bcdefgh';});
check('extractContents moves fully selected node identity',function(){var n=box('<b>abc</b><i>def</i><u>ghi</u>'),middle=n.childNodes[1],r=new Range();r.setStart(n.firstChild.firstChild,1);r.setEnd(n.lastChild.firstChild,2);var f=r.extractContents();return f.childNodes[1]===middle&&f.textContent==='bcdefgh'&&n.textContent==='ai'&&r.collapsed;});
check('deleteContents spans partial elements',function(){var n=box('<b>abc</b><i>def</i><u>ghi</u>'),r=new Range();r.setStart(n.firstChild.firstChild,1);r.setEnd(n.lastChild.firstChild,2);r.deleteContents();return n.textContent==='ai'&&n.childNodes.length===2&&r.collapsed&&r.startContainer===n&&r.startOffset===1;});
check('deleteContents preserves text identity',function(){var n=box('abcdef'),t=n.firstChild,r=new Range();r.setStart(t,2);r.setEnd(t,4);r.deleteContents();return n.firstChild===t&&t.data==='abef'&&r.collapsed&&r.startOffset===2;});
check('insertNode splits text and selects inserted node',function(){var n=box('abcd'),r=new Range(),b=document.createElement('b');b.textContent='X';r.setStart(n.firstChild,2);r.collapse(true);r.insertNode(b);return n.childNodes.length===3&&n.textContent==='abXcd'&&r.endContainer===n&&r.endOffset===2&&r.toString()==='X';});
check('insertNode inserts fragment children',function(){var n=box('<b>a</b>'),r=new Range(),f=document.createDocumentFragment();f.appendChild(document.createTextNode('x'));f.appendChild(document.createTextNode('y'));r.setStart(n,1);r.collapse(true);r.insertNode(f);return n.textContent==='axy'&&f.childNodes.length===0&&r.startOffset===1&&r.endOffset===3;});
check('createContextualFragment builds detached widget DOM',function(){var r=document.createRange(),f=r.createContextualFragment('<div class="quality"><b>720P</b></div>');return f.nodeType===11&&f.childNodes.length===1&&f.firstChild.parentNode===f&&f.firstChild.className==='quality'&&f.firstChild.firstChild.textContent==='720P';});
check('createContextualFragment honors table context',function(){var table=document.createElement('table'),r=document.createRange();r.selectNodeContents(table);var f=r.createContextualFragment('<tbody><tr><td>HD</td></tr></tbody>');return f.firstChild.tagName==='TBODY'&&f.firstChild.firstChild.tagName==='TR'&&f.firstChild.firstChild.firstChild.textContent==='HD';});
check('createContextualFragment honors select text parent',function(){var select=document.createElement('select');select.textContent='seed';var r=document.createRange();r.selectNodeContents(select.firstChild);var f=r.createContextualFragment('<option value="64">720P</option>');return f.childNodes.length===1&&f.firstChild.tagName==='OPTION'&&f.firstChild.value==='64'&&f.firstChild.textContent==='720P';});
check('createContextualFragment scripts stay inert on insertion',function(){globalThis.__rangeFragmentScript=0;var r=document.createRange(),f=r.createContextualFragment('<script>globalThis.__rangeFragmentScript++<\/script><i>x</i>');document.body.appendChild(f);return globalThis.__rangeFragmentScript===0&&document.body.lastChild.tagName==='I';});
check('cloneRange is independently live',function(){var t=document.createTextNode('abcd'),r=new Range();r.setStart(t,1);r.setEnd(t,3);var copy=r.cloneRange();r.collapse(true);t.insertData(0,'z');return r.collapsed&&copy.startOffset===2&&copy.endOffset===4;});
check('cross shadow compare refuses',function(){var n=box('abc'),host=document.createElement('div');n.appendChild(host);var shadow=host.attachShadow({mode:'open'}),t=document.createTextNode('xyz');shadow.appendChild(t);var a=new Range(),b=new Range();a.selectNodeContents(n.firstChild);b.selectNodeContents(t);try{a.compareBoundaryPoints(0,b);}catch(e){return e.name==='WrongDocumentError';}return false;});
check('different roots collapse when setting endpoint',function(){var a=document.createTextNode('a'),b=document.createTextNode('b'),r=new Range();r.selectNodeContents(a);r.setEnd(b,1);return r.startContainer===b&&r.collapsed;});
check('substringData counts UTF16',function(){var t=document.createTextNode('A😀Z');return t.substringData(1,2)==='😀';});
check('appendData leaves boundary at original end',function(){var t=document.createTextNode('a😀'),r=new Range();r.setStart(t,3);r.collapse(true);t.appendData('Z');return r.startOffset===3&&t.data==='a😀Z';});
var passed=checks.filter(function(c){return c.ok;}).length;
var out=document.getElementById('range-result');
if(out){out.textContent='Range: '+passed+'/'+checks.length+' PASS'+checks.filter(function(c){return !c.ok;}).map(function(c){return '\nFAIL '+c.name+' '+c.error;}).join('');out.setAttribute('data-pass',passed===checks.length?'true':'false');}
})(globalThis);
